\begin{equation}\label{prob:main}
\tag{$\text{P}^f_{\text{VI}}$} 
\begin{aligned}
& {\text{minimize}}
& & f(x) \\
& \text{subject to}
& & x \in \text{SOL}(X,F).
\end{aligned}
\end{equation}

Here, $f:\mathbb{R}^n \to \mathbb{R}$ is a convex function and $X \subseteq \mathbb{R}^n$ is given as a Cartesian product, i.e., $ X \triangleq \prod_{i = 1}^{d}  X_i $, where $X_i \subseteq\mathbb{R}^{n_i}$ is convex for all $i=1,\dots, d$ and $\sum_{i=1}^dn_i=n$. We consider $F: X \to \mathbb{R}^n$ to be a monotone mapping. The term $\text{SOL}(X,F)$ denotes the solution set of the variational inequality $\text{VI}(X,F)$ defined as follows:  A vector $x \in X$ is said to be a solution to $\text{VI}(X,F)$ if for any $y \in X$, we have $F(x)^T(y-x) \geq 0$. Variational inequalities, first introduced in late 1950s, are an immensely powerful mathematical tool that can serve as a unifying framework for capturing a wide range of applications arising in operations research, finance, and economics (cf. \cite{FacchineiPang2003, Rockafellar98,Lan-VI-13,wang2015}). Importantly, as it will be discussed shortly, the block structure of the set $X$ allows for addressing Nash games as well as high-dimensional optimization problems. We note that the problem \cref{prob:main} can represent a variety of the standard problems in optimization and VI regimes. For example, when $F(x) := 0_{n}$, the problem \cref{prob:main} is equivalent to the canonical optimization problem $\min_{x \in X} f(x)$. Also, when $f(x):=0$, the problem \cref{prob:main} is equivalent to solving $\text{VI}(X,F)$. More detailed examples that can be reformulated as the problem \cref{prob:main} are presented below.


\textbf{Notation and preliminary definitions:} Throughout, a vector $ x \in \mathbb{R}^n$ is assumed to be a column vector and $ x^T$ denotes the transpose of $x$. We use $x^{(i)}\in \mathbb{R}^{n_i}$ to denote the $i^{\text{th}}$ block-coordinate of vector $x$ where $x =\left(x^{(1)};\ldots;x^{(d)}\right)$ and $\sum_{i=1}^dn_i=n$. The Euclidean norm of a vector $x$ is denoted by $\|x\|$, i.e.,  $\| x\|\triangleq \sqrt{ x^T  x}.$  For a mapping $F:\mathbb{R}^n \to \mathbb{R}^n$, we denote the $i^{\text{th}}$ block-coordinate of $F$ by $F_i:\mathbb{R}^n \to \mathbb{R}^{n_i}$, i.e., $F(x) =\left(F_1(x);\ldots;F_d(x)\right)$. A mapping $F:\mathbb{R}^n \to \mathbb{R}^n$ is said to be monotone on a convex set $X \subseteq \mathbb{R}^n$ if for any $x,y \in X$, we have $(F(x)-F(y))^T(x-y)\geq 0$. The mapping $F$ is said to be $\mu$--strongly monotone on a convex set $X \subseteq \mathbb{R}^n$ if $\mu>0$ and for any $x,y \in X$, we have $(F(x)-F(y))^T(x-y)\geq \mu\|x-y\|^2$. Also, $F$ is said to be Lipschitz with parameter $L>0$ on the set $X$ if for any $x,y \in X$, we have $\|F(x)-F(y)\|\leq L\|x-y\|$. A continuously differentiable function $f:\mathbb{R}^n \to \mathbb{R}$ is called $\mu$--strongly convex on a convex set $X$ if $f(x) \geq f(y)+\nabla f(y)^T(x-y)+\frac{\mu}{2}\|x-y\|^2$. Function $f$ is $\mu$--strongly convex if and only if $\nabla f$ is $\mu$--strongly monotone on $X$. For a convex function $f$ with the domain $\text{dom}(f)$, the subgradient of $f$ at $x \in \text{dom}(f)$ is denoted by $\tilde \nabla f(x)$ and it satisfies $f(x)+\tilde \nabla f(x)^T(y-x) \leq f(y)$ for all $y \in \text{dom}(f)$. The subdifferential set of $f$ at $x$ is the set of all subgradients of $f$ at $x$ and is denoted by $\partial f(x)$. The Euclidean projection of vector $s$ onto a convex set $ S$ is denoted by $ \proj[S]{ s} $, where $\proj[S]{ s}\triangleq  \argmin_{ y \in  S}\| s- y\|$. %Given two vectors $x,y\in \mathbb{R}^n$, we use $0\leq x \perp y \geq 0$ to compactly denote the complementarity constraints $x\geq 0$, $y \geq 0$, and $x^Ty=0$. 


We use $\mathbf{I}_n$ to denote the identity matrix of size $n\times n$. The probability of an event $Z$ is denoted by $\text{Prob}(Z)$ and the expectation of a random variable $z$ is denoted by $\EXP{z}$. We use $\mathbb{R}^n_+$ and $\mathbb{R}^n_{++}$ to denote $\{x \in \mathbb{R}^n \mid x \geq 0\}$ and  $\{x \in \mathbb{R}^n \mid x > 0\}$, respectively.


\begin{assumption}\label{assum:problem} Consider the problem \cref{prob:main} under the following conditions:

\noindent (a) The set $X_i$ is nonempty, closed, and convex for all $i=1,\dots, d$.

\noindent (b) The function $f$ is convex and has bounded subgradients over the set $X$.

\noindent  (c) The mapping $F:\mathbb{R}^n \to \mathbb{R}^n$ is continuous, monotone, and bounded over the set $X$. 

\noindent (d) The optimal solution set of problem \cref{prob:main} in nonempty.
\end{assumption}

Throughout, we let $C_F>0$ denote the bound on the Euclidean norm of the mapping $F$, i.e., $\|F(x)\| \leq C_F$ for all $x \in X$. Also, we let $C_f>0$ denote the bound on the norm of the subgradients of $f$, i.e., $\|\tilde \nabla f (x)\| \leq C_f$ for all $\tilde \nabla f(x) \in \partial f(x)$ and $x \in X$.
\begin{algorithm} [h]
	\caption{aRB-IRG}
	\begin{algorithmic}[1]
		\STATE\textbf{Input:} A random initial point $x_0 \in X$, $\bar{x}_0 := x_0$, initial stepsize $\gamma_{0} > 0$, initial regularization parameter $\eta_{0} > 0$, a scalar $0\leq r<1$, and $S_0 := \gamma_0^r$.
		\FOR{k = 0, 1, \dots}
		\STATE Generate a realization of random variable $i_k$ according to \cref{assum:random sample}.
		\STATE Evaluate $F_{i_k}(x_k)$ and $\tilde \nabla_{i_k} f(x_k)$ where $\tilde \nabla f(x_k) \in \partial f(x_k)$.

		\STATE Update $x_k$ as follows:
%				${x_{k+1}^{(i)}} :=$
		\begin{align}\label{equ:update_rule_aRBIRG} 
		{x_{k+1}^{(i)}} :=
		\begin{cases}
		\proj[X_{i_k}]{ x_{k}^{(i_k)}-\gamma_{k}\left(F_{i_k}\left( x_{k}\right) + \eta_{k} \tilde \nabla_{{i_k}} f\left( x_{k}\right)\right)}& \text{ if } i = i_k, \\
		x_k^{(i)} & \text{ if } i \neq i_k. 
		\end{cases}
		\end{align}
		\STATE Obtain $\gamma_{k+1}$ and $\eta_{k+1}$ (cf. \cref{thm:a-IRG_rate_results} and \cref{thm:convergence_RB-IRG} for the update rules).

		\STATE Update the averaged iterate $\bar{x}_{k}$ as follows:
			\begin{align}\label{eqn:ave_step_of_alg}
			S_{k+1} &:= S_k + \gamma_{k+1}^r,\quad	\bar{x}_{k+1}:= \frac{S_k\bar{x}_{k}+\gamma_{k+1}^rx_{k+1}}{S_{k+1}}.
			\end{align}
		\ENDFOR
	\end{algorithmic} \label{alg:aRB-IRG}
\end{algorithm}

\begin{assumption}[Block-coordinate selection rule] \label{assum:random sample}
At each iteration $k\geq 0$, the random variable $i_k$ is generated from an independent and identically distributed discrete probability distribution such that $\mathrm{Prob}\left(i_k=i\right) = \prob{i}$ where $ \prob{i}>0$ for $i \in \{1,\ldots,d\}$ and $\sum_{i=1}^{d}\prob{i}=1$.
\end{assumption}

\begin{definition}[Distance function]\label{def:err_D}
	For any $x,y \in \mathbb{R}^n$, function $\mathcal{D}(x,y)$ is defined as $
	\mathcal{D}(x,y)\triangleq \sum_{i=1}^{d} \prob{i}^{-1} \left\Vert\left. x^{(i)}-y^{(i)} \right\Vert\right.^2$, where $\prob{i}$ is given by \cref{assum:random sample}.
	% 	, where $\prob{i}$ is the uniform probability of selection of any block  $i$. From \cref{assum:random sample}, we have $\prob{i} = \frac{1}{d}.$ So, we write  $ \mathcal{D}(x,y) =  d \sum_{i=1}^{d}  \left\Vert\left. x^{(i)}-y^{(i)} \right\Vert\right.^2$.
\end{definition}

\begin{remark} \label{rem:err_D}
Under \cref{assum:random sample}, we can relate the distance function $\mathcal{D}$ with the $\ell_2$--norm as follows: $\prob{{min}}	{\mathcal{D}(x,y)} \leq \|x-y\|^2 \leq\prob{{max}} {\mathcal{D}(x,y)}$ for all $x,y \in \mathbb{R}^n$, where  $\prob{{min}}\triangleq \min_{1\leq i \leq d}\{\prob{i}\}$ and $\prob{{max}}\triangleq \max_{1\leq i \leq d}\{\prob{i}\}$.
\end{remark}

\begin{definition}[The dual gap function \cite{MarcotteZhu1998}]\label{def:gap}
Let a nonempty closed set $X\subseteq \mathbb{R}^n$ and a mapping $F:X\rightarrow\mathbb{R}^n$ be given. Then, for any $x \in X$, the dual gap function $\mathrm{GAP}:X\rightarrow \mathbb{R}\cup \{+\infty\} $ is defined as $ \mathrm{GAP}(x) \triangleq \sup_{y\in X} F(y)^T(x-y)$.
\end{definition}

\begin{definition}[Regularized mapping]\label{def:reg_map}
Given a vector $x \in X$, a subgradient $\tilde \nabla f(x) \in \partial f(x)$, and an integer $k\geq 0$, the regularized mapping $G_k: X \to \mathbb{R}$ is defined as $G_k(x) \triangleq F(x)+\eta_k\tilde \nabla f(x)$. The $i^\text{th}$ {block-coordinate} of $G_k$ is denoted by $G_{k,i}$.
\end{definition}

\begin{definition}[History of the method]\label{def:Fk}
Throughout, we let the history of the algorithm to be denoted by $\mathcal{F}_k \triangleq \{x_0,i_0,i_1,\ldots,i_{k-1}\}$ for $k\geq 1$, with $\mathcal{F}_0 \triangleq \{x_0\}$.
\end{definition}

\begin{definition}[Randomized block error terms]\label{def:deltas}
Let ${\mathbf{U}}_i \in \mathbb{R}^{n\times n_i}$ for $i=1,\ldots,d$ be the collection of matrices such that $\mathbf{I}_n = \left[{\mathbf{U}}_1,\ldots,{\mathbf{U}}_d\right] \in \mathbb{R}^{n\times n}$. Consider the following definitions for $k\geq 0$: 
\begin{align}\label{eqn:deltas}
\Delta_k\triangleq F(x_k) - \prob{{i_k}}^{-1}{\mathbf{U}}_{i_k}F_{i_k}(x_k), \qquad \delta_k\triangleq \tilde \nabla f(x_k) - \prob{{i_k}}^{-1}{\mathbf{U}}_{i_k} \tilde \nabla_{i_k}f (x_k).
\end{align}
\end{definition}

