\begin{lemma}[Weighted averaging]\label{Lemma 2.10}
Let $\{\bar x_k\}$ be generated by \cref{alg:aRB-IRG}. Let us define the weights $\lambda_{k,N} \triangleq \frac{\gamma_k^r}{\sum_{j=0}^N \gamma_j^r}$ for $k \in \{0,\ldots, N\}$ and $N\geq 0$. Then, for any $N\geq 0$, we have $\bar{x}_{N} = \sum_{k=0}^N \lambda_{k,N} x_k$. Also, when $X$ is a convex set, we have $\bar x_N \in X$.
\end{lemma}

\begin{proof}
\begin{comment}
We use induction to show that $\bar{x}_{N} = \sum_{k=0}^N \lambda_{k,N} x_k$ for any $N\geq 0$. For $N=0$, the relation holds due to the initialization $\bar{x}_0 :=x_0$ in \cref{alg:aRB-IRG} and that $\lambda_{0,0}=1$. Next, let the relation hold for some $N\geq 0$. From \cref{eqn:ave_step_of_alg} and noting that $S_{N}=\sum_{k=0}^N\gamma_k^r$ for any $N\geq 0$, we can write the following: 
\begin{align*}
	\bar{x}_{N+1} = \frac{S_N\bar{x}_N + \gamma_{N+1}^r x_{N+1}}{S_{N+1}} 
	%= \frac{\sum_{k = 0}^{N}\gamma_k^r x_k + \gamma_{N+1}^r x_{N+1}}{S_{N+1}}
	 = \frac{\sum_{k=0}^{N+1}\gamma_k^r x_k}{\sum_{k = 0}^{N+1}\gamma_k^r} = \sum_{k=0}^{N+1} \lambda_{k,N+1} x_k,
	\end{align*}
implying that the induction hypothesis holds for $N+1$. Thus, we conclude that the desired averaging formula holds for $N\geq 0$. To complete the proof, note that since $\sum_{k=0}^N \lambda_{k,N}=1$, under the convexity of the set $X$, we have $\bar x_N \in X$.
\end{comment}
See \cref{app:ave_x_second_formula}. 
\end{proof}

\begin{lemma}[Properties of $\Delta_k$ and $\delta_k$]\label{Lemma 2.12}
Consider \cref{def:deltas}. We have:\\
\noindent (a)  $\EXP{\Delta_k\mid \mathcal{F}_k}=\EXP{\delta_k\mid \mathcal{F}_k}=0$.\\
\noindent (b) $\EXP{\|\Delta_k\|^2\mid \mathcal{F}_k} \leq  \left(\prob{{min}}^{-1}-1\right)C_F^2$ and $\EXP{\|\delta_k\|^2\mid \mathcal{F}_k} \leq  \left(\prob{{min}}^{-1}-1\right)C_f^2$.
\end{lemma}

\begin{proof} 
\begin{comment}
\noindent (a) From the definition of $\Delta_k$ and ${\mathbf{U}}_i $, we can write:
\begin{align*} 
\EXP{\Delta_k\mid \mathcal{F}_k} =F(x_k)-\sum_{i=1}^d\prob{{i}}\prob{{i}}^{-1}{\mathbf{U}}_{i}F_{i}(x_k)= F(x_k) -\sum_{i=1}^d{\mathbf{U}}_{i}F_{i}(x_k) =0.
\end{align*}
The relation $\EXP{\delta_k\mid \mathcal{F}_k}=0$ can be shown in a similar fashion.

\noindent (b) We can write:
\begin{align*}
 \EXP{\|\Delta_k\|^2\mid \mathcal{F}_k}& = \sum_{i=1}^d\prob{{i}}\left\|F(x_k)-\prob{{i}}^{-1}{\mathbf{U}}_{i}F_{i}(x_k)\right\|^2\\
 &=  \sum_{i=1}^d\prob{{i}} \left(\|F(x_k)\|^2 +\prob{{i}}^{-2} \left\|{\mathbf{U}}_{i}F_{i}(x_k)\right\|^2 - 2\prob{{i}}^{-1}F(x_k)^T{\mathbf{U}}_{i}F_{i}(x_k)\right)\\
 & = \|F(x_k)\|^2 +\sum_{i=1}^d\prob{{i}}^{-1} \left\|{\mathbf{U}}_{i}F_{i}(x_k)\right\|^2  -2\sum_{i=1}^d\|F_i(x_k)\|^2\\
 & \leq \left(\prob{{min}}^{-1}-1\right)\|F(x_k)\|^2 \leq \left(\prob{{min}}^{-1}-1\right)C_F^2.
\end{align*}
The relation $\EXP{\|\delta_k\|^2\mid \mathcal{F}_k} \leq  \left(\prob{{min}}^{-1}-1\right)C_f^2$ can be shown using a similar approach. 
\end{comment}
See \cref{app:deltas}
\end{proof}

\begin{lemma}[Bounds on the harmonic series]\label{Lemma 2.13}
Let $0\leq \alpha <1$ be a given scalar. Then, for any integer $N \geq 2^{\frac{1}{1-\alpha}}-1$, we have 
%\begin{align*}
$\frac{(N+1)^{1-\alpha}}{2(1-\alpha)}  \leq \sum_{k=0}^{N}\frac{1}{(k+1)^\alpha}\leq \frac{(N+1)^{1-\alpha}}{1-\alpha}$.
%\end{align*}
\end{lemma}

\begin{proof}
