\begin{lemma}\label{lem:prebound_gap}
Consider the sequence $\{x_k\}$ in \cref{alg:aRB-IRG}. Suppose $\{\gamma_k\}$ and $\{\eta_k\}$ are strictly positive sequences. Let \cref{assum:problem} and \cref{assum:random sample} hold. Let the auxiliary sequence $\{u_k\} \subset X$ be defined as 
		%\begin{align}\label{equ:update_rule_aux_u} 
		{$u_{k+1} \triangleq \mathcal{P}_X\left(u_k-\gamma_k\left(\Delta_k+\eta_k\delta_k\right)\right)$},
		%\end{align}
where $u_0 \in X$ is an arbitrary vector. Then, for {all $y\in X$ and all $k \geq 0$, we have}:
\begin{align}\label{eqn:prebound_gap}
&\gamma_k^rF(y)^T(x_k-y) +\gamma_k^r\eta_k\tilde \nabla f(x_k)^T(x_k-y)\leq \frac{\gamma_k^{r-1}}{2}\left(\mathcal{D}\left(x_{k}, y\right) +\|u_k-y\|^2\right) \nonumber\\
&-\frac{\gamma_k^{r-1}}{2}\left(\mathcal{D}\left(x_{k+1}, y\right) +\|u_{k+1}-y\|^2\right){+ \gamma_k^r(x_k-u_k)^T\left(\Delta_k+\eta_k\delta_k\right)}\nonumber\\
& +\gamma_k^{r+1}\left(\|\Delta_k\|^2+\eta_k^2\|\delta_k\|^2\right)+ 0.5\prob{{i_k}}^{-1}\gamma_k^{1+r}\left\Vert\left.G_{k,i_k}\left(x_k\right)\right\Vert\right.^2.
\end{align}
\end{lemma}

\begin{proof} Let $k\geq 1$ be fixed. From \cref{def:err_D} and \cref{equ:update_rule_aRBIRG}, for any $y \in X$, we have:
	\begin{align}\label{eqn:D_split}
	\mathcal{D} \left(x_{k+1}, y\right)  =   \prob{{i_k}}^{-1} \left\Vert\left.  x_{k+1}^{(i_k)}-  y^{(i_k)} \right\Vert\right.^2+\sum_{i=1, \thinspace	 i \neq i_k}^{d} \prob{i}^{-1} \left\Vert\left.  x_{k}^{(i)}-  y^{(i)} \right\Vert\right.^2.
	\end{align}Next, we find a bound on the term $\left\Vert\left.  x_{k+1}^{(i_k)}- y^{(i_k)} \right\Vert\right.^2$. From the block structure of $X$, we have $y^{(i_k)}\in X_{i_k}$. Invoking the nonexpansiveness property of the projection mapping, the update rule \cref{equ:update_rule_aRBIRG}, \cref{def:reg_map}, and the preceding relation, we obtain:
		\begin{align*} 
	\left\Vert\left. x_{k+1}^{(i_k)}-  y^{(i_k)}\right\Vert\right.^2 \leq\left\Vert\left.  x_{k}^{(i_k)}-\gamma_{k}G_{k,i_k} \left( x_{k}\right) -y^{(i_k)}\right\Vert\right.^2.
	\end{align*}
		Combining the preceding relation with \cref{eqn:D_split}, we obtain:
	\begin{align*}
	 	\mathcal{D}\left(x_{k+1}, y\right)& \leq 
	 	 \sum_{i=1, \thinspace	 i \neq i_k}^{d} \prob{i}^{-1} \left\Vert\left.  x_{k}^{(i)}-  y^{(i)} \right\Vert\right.^2 +  \prob{{i_k}}^{-1}\left\Vert\left.  x_{k}^{(i_k)}-  y^{(i_k)} \right\Vert\right.^2 \nonumber \\
& - 2\,\prob{{i_k}}^{-1}\gamma_k\left( x^{(i_k)}_{k} - y^{(i_k)}\right)^TG_{k,i_k}\left(x_k\right)+ \prob{{i_k}}^{-1}\gamma_k^2 \left\Vert\left.G_{k,i_k}\left(x_k\right)\right\Vert\right.^2.
	\end{align*}
Invoking \cref{def:err_D} again, we obtain:	
		\begin{align}\label{eqn:erc_D_elementary_ineq1}
	 	\mathcal{D}\left(x_{k+1}, y\right) & \leq  \mathcal{D}\left(x_{k}, y\right) - 2\,\prob{{i_k}}^{-1}\gamma_k\left( x^{(i_k)}_{k} - y^{(i_k)}\right)^TG_{k,i_k}\left(x_k\right)+ \prob{{i_k}}^{-1}\gamma_k^2 \left\Vert\left.G_{k,i_k}\left(x_k\right)\right\Vert\right.^2.
	\end{align}
From \cref{def:deltas} and \cref{def:reg_map}, we can write:
\begin{align*}
&\prob{{i_k}}^{-1}\left( x^{(i_k)}_{k} - y^{(i_k)}\right)^TG_{k,i_k}\left(x_k\right) = \prob{{i_k}}^{-1}(x_k-y)^T\left({\mathbf{U}}_{i_k}G_{k,i_k}\left(x_k\right)\right) \\ 
&=  \prob{{i_k}}^{-1}(x_k-y)^T\left({\mathbf{U}}_{i_k}F_{i_k}(x_k)+\eta_k{\mathbf{U}}_{i_k}\tilde \nabla_{i_k}f\left(x_k\right)\right) \\
& {=(x_k-y)^T\left(F(x_k)-\Delta_k+\eta_k\tilde \nabla f(x_k)-\eta_k\delta_k\right) = (x_k-y)^T\left(G_k(x_k)-\Delta_k-\eta_k\delta_k\right).}
\end{align*}
	Combining the preceding inequality and relation \cref{eqn:erc_D_elementary_ineq1}, we obtain:
	\begin{align}\label{eqn:erc_D_elementary_ineq2}
	 	\mathcal{D}\left(x_{k+1}, y\right) & \leq  \mathcal{D}\left(x_{k}, y\right) {- 2 \gamma_k(x_k-y)^T\left(G_k(x_k)-\Delta_k-\eta_k\delta_k\right)}+ \prob{{i_k}}^{-1}\gamma_k^2 \left\Vert\left.G_{k,i_k}\left(x_k\right)\right\Vert\right.^2.
	\end{align}
	Consider the definition of the auxiliary sequence $\{u_k\}$ in \cref{lem:prebound_gap}. Invoking the nonexpansiveness property of the projection again, we can obtain:
\begin{align*}
\|u_{k+1}-y\|^2  &\leq{\|u_k-\gamma_k\left(\Delta_k+\eta_k\delta_k\right)-y\|^2}\\
&=\|u_k-y\|^2{-2\gamma_k(u_k-y)^T\left(\Delta_k+\eta_k\delta_k\right)} + \gamma_k^2\|\Delta_k+\eta_k\delta_k\|^2.
\end{align*}
Thus, we have: 
\begin{align*}
\|u_{k+1}-y\|^2\leq \|u_k-y\|^2{- 2\gamma_k(u_k-y)^T\left(\Delta_k+\eta_k\delta_k\right)} +2\gamma_k^2\|\Delta_k\|^2+2\gamma_k^2\eta_k^2\|\delta_k\|^2.
\end{align*}
Adding the preceding inequality and the inequality \cref{eqn:erc_D_elementary_ineq2} together, we obtain:
\begin{align}\label{eqn:erc_D_elementary_ineq3}
&2\gamma_k(x_k-y)^T G_k(x_k) \leq \left(\mathcal{D}\left(x_{k}, y\right) +\|u_k-y\|^2\right) -\left(\mathcal{D}\left(x_{k+1}, y\right) +\|u_{k+1}-y\|^2\right)\nonumber\\
& {+ 2\gamma_k(x_k-u_k)^T\left(\Delta_k+\eta_k\delta_k\right)}+2\gamma_k^2\left(\|\Delta_k\|^2+\eta_k^2\|\delta_k\|^2\right)+ \prob{{i_k}}^{-1}\gamma_k^2 \left\Vert\left.G_{k,i_k}\left(x_k\right)\right\Vert\right.^2.
\end{align}
From the monotonicity property of the mapping $F$ and \cref{def:reg_map}, we have:
\begin{align*}
(x_k-y)^TG_k(x_k)
%=(x_k-y)^T\left(F(x_k)+\eta_k\tilde \nabla f(x_k)\right) 
\geq (x_k-y)^TF(y)+\eta_k\tilde \nabla f(x_k)^T(x_k-y).
\end{align*}
This provides a lower bound on the left-hand side of \cref{eqn:erc_D_elementary_ineq3}. The inequality \cref{eqn:prebound_gap} is obtained by substituting this bound in \cref{eqn:erc_D_elementary_ineq3} and multiplying both sides by $\frac{\gamma_{k}^{r-1}}{2}$.
\end{proof}

\begin{proposition}[Error bounds for \cref{alg:aRB-IRG}]\label{prop:dual_gap_bound}
Let the sequence $\{\bar x_k\}$ be generated by \cref{alg:aRB-IRG}{, where $0\leq r<1$}. Suppose $\{\gamma_k\}$ and $\{\eta_k\}$ are strictly positive and nonincreasing sequences. Let \cref{assum:problem} and \cref{assum:random sample} hold {and} assume {that} the set $X$ is bounded, i.e., {$\|x\|\leq M$} for all $x \in X$ and some $M>0$. \\
\noindent (a) Let $x^*$ be an optimal solution to problem \cref{prob:main}. Then, for {all} $N\geq 1$:
\begin{align}\label{eqn:f_bound} 
&\EXP{f\left(\bar x_N\right)}-f(x^*) \leq \frac{\frac{4M^2\gamma_{{N}}^{r-1}}{\eta_{N}} +\sum_{k=0}^{N}\eta_k^{-1}\gamma_k^{r+1}\left(C_F^2+\eta_k^2C_f^2\right)}{\prob{{min}}\sum_{k=0}^{N}\gamma_k^r}.
\end{align}
\noindent (b) Consider the dual gap function in \cref{def:gap}. Then, for {all} $N\geq 1$:
\begin{align}\label{eqn:gap_bound} 
\EXP{\mathrm{GAP}\left(\bar{x}_N\right)} \leq\frac{ {4 M^2 \gamma_{{N}}^{r-1} }  +\sum_{k=0}^{N}\gamma_{{k}}^r\left( 2\prob{{min}}\eta_kC_fM+\gamma_k C_F^2 +  \gamma_{k}\eta_k^2C_f ^2 \right)}{\prob{{min}}\sum_{k=0}^{N} \gamma_{{k}}^r}.
\end{align}
\end{proposition}

\begin{proof}
We define the following terms for all $k\geq 0$, that appear in \cref{eqn:prebound_gap}:
\begin{align}\label{eqn:three_terms_abr}
& {\Theta_{k,1} \triangleq \gamma_k^r(x_k-u_k)^T\left(\Delta_k+\eta_k\delta_k\right)}, \quad \Theta_{k,2} \triangleq \gamma_k^{r+1}\left(\|\Delta_k\|^2+\eta_k^2\|\delta_k\|^2\right),\nonumber \\ 
&\Theta_{k,3} \triangleq 0.5\prob{{i_k}}^{-1}\gamma_k^{1+r}\left\Vert\left.G_{k,i_k}\left(x_k\right)\right\Vert\right.^2.
\end{align}
Next, we estimate the expected values of these terms. {Consider the notation of} $\mathcal{F}_k$ given by \cref{def:Fk}. Note that $x_k$ is $\mathcal{F}_k$--measurable. Also, from the definition of $u_k$ in \cref{lem:prebound_gap}, $u_k$ is $\mathcal{F}_k$--measurable. Note, however, that $\Theta_{k,j}$ is $\mathcal{F}_{k+1}$--measurable for all $j \in \{1,2,3\}$. Taking these into account and using the total probability law, for any $k\geq 0$ and $j \in \{1,2,3\}$, we have $ \EXP{\Theta_{k,j}} = \mathsf{E}_{\mathcal{F}_k}\left[\mathsf{E}_{i_k}\left[\Theta_{k,j}\mid \mathcal{F}_k\right]\right]$. From this relation and \cref{Lemma 2.12}, we have for any $k\geq 0$:
\begin{align}\label{eqn:estimate_deltas_1_2}
&\EXP{\Theta_{k,1}} = 0, \qquad \EXP{\Theta_{k,2}} = \left(\prob{{min}}^{-1}-1\right)\gamma_k^{r+1}\left(C_F^2+\eta_k^2C_f^2\right).
\end{align}
Also, using \cref{def:reg_map} and the triangle inequality, we can write:
\begin{align*}
&{\mathsf{E}_{i_k}\left[\Theta_{k,3}\mid \mathcal{F}_k\right]} = \sum_{i=1}^d\prob{i}\left(0.5\prob{{i}}^{-1}\gamma_k^{1+r}\left\Vert\left.G_{k,i}\left(x_k\right)\right\Vert\right.^2\right)\nonumber\\
&\leq \gamma_k^{1+r}\sum_{i=1}^d\left(\|F_i(x_k)\|^2+\eta_k^2\|\tilde \nabla_i f(x_k)\|^2\right)  = \gamma_k^{1+r}\|F(x_k)\|^2+\eta_k^2\|\tilde \nabla f(x_k)\|^2.
\end{align*}
{From the preceding inequality, we obtain:
\begin{align}\label{eqn:estimate_deltas_3}
\EXP{\Theta_{k,3}} & \leq  \gamma_k^{1+r}\left(C_F^2+\eta_k^2C_f^2\right).
\end{align}
}We are now ready to show the inequalities \cref{eqn:f_bound} and \cref{eqn:gap_bound} as follows:\\
\noindent (a) Consider \cref{eqn:prebound_gap}. From the definition of subgradients of the convex function $f$, we have that $f(x_k)-f(y) \leq \tilde \nabla f(x_k)^T(x_k-y)$. Thus, {from \cref{eqn:three_terms_abr}} we obtain for any $y \in X$:
\begin{align*}
&\gamma_k^rF(y)^T(x_k-y) +\gamma_k^r\eta_k\left(f(x_k)-f(y)\right)\leq \frac{\gamma_k^{r-1}}{2}\left(\mathcal{D}\left(x_{k}, y\right) +\|u_k-y\|^2\right) \nonumber\\
&-\frac{\gamma_k^{r-1}}{2}\left(\mathcal{D}\left(x_{k+1}, y\right) +\|u_{k+1}-y\|^2\right)+ \Theta_{k,1}+\Theta_{k,2}+\Theta_{k,3}.
\end{align*}
Let us substitute $y:=x^*$, where $x^*$ denotes an optimal solution to \cref{prob:main}. Note that $x^*$ must be a feasible solution to \cref{prob:main}, i.e., $F(x^*)^T(x_k-x^*) \geq 0$. Thus, we obtain:
\begin{align}\label{eqn:gap_prop_ineq1_a}
			&\gamma_k^r\eta_k\left(f(x_k)-f(x^*)\right) \leq  \frac{\gamma_k^{r-1}}{2}\left(\mathcal{D}\left(x_{k}, x^*\right) +\|u_k-x^*\|^2\right) \nonumber\\
&-\frac{\gamma_k^{r-1}}{2}\left(\mathcal{D}\left(x_{k+1}, x^*\right) +\|u_{k+1}-x^*\|^2\right)+\Theta_{k,1}+\Theta_{k,2}+\Theta_{k,3}.
\end{align}
Dividing both sides by $\eta_k$ and adding and subtracting $\frac{\gamma_{{k-1}}^{r-1}}{2\eta_{k-1}} \left( \mathcal{D}\left(x_k,x^*\right) + \left\Vert u_k-x^* \right\Vert^2 \right)$ in the right-hand side of \cref{eqn:gap_prop_ineq1_a}, we obtain for $k\geq 1$:
\begin{align}\label{eqn:gap_prop_ineq2_a}
&\gamma_k^r\left(f(x_k)-f(x^*)\right) \leq  \frac{\gamma_{{k-1}}^{r-1}}{2\eta_{k-1}} \left(  \mathcal{D}\left(x_k,x^*\right)  + \left\Vert u_k-x^* \right\Vert^2 \right) \nonumber \\
&- \frac{\gamma_{{k}}^{r-1}}{2\eta_k} \left(  \mathcal{D}\left(x_{k+1},x^*\right)  + \left\Vert u_{k+1}-x^* \right\Vert^2 \right)\nonumber \\ 
&+ \frac{1}{2} \left(\frac{\gamma_{{k}}^{r-1}}{\eta_k} - \frac{\gamma_{{k-1}}^{r-1}}{\eta_{k-1}}\right)\left( \mathcal{D}\left(x_k,x^*\right) + \left\Vert u_k-x^* \right\Vert^2 \right)+\eta_k^{-1}\left( \Theta_{k,1}+\Theta_{k,2}+\Theta_{k,3}\right).
\end{align}
Since $r-1 < 0$ and that $\{\gamma_k\}$ and $\{\eta_k\}$ are nonincreasing, we have $\frac{\gamma_{{k}}^{r-1}}{\eta_k} - \frac{\gamma_{{k-1}}^{r-1}}{\eta_{k-1}} \geq 0$. Also, from the boundedness of the set $X$, since $x_k$, $x^*$, and {$u_k$} belong to $ X$, using \cref{rem:err_D} and the triangle inequality, we have:
\begin{align}\label{eqn:gap_prop_ineq3_a}
\mathcal{D}\left(x_k,x^*\right)  + \left\Vert u_k-x^* \right\Vert^2 
\leq \prob{{min}}^{-1}\left\Vert x_k-x^* \right\Vert^2 + \left\Vert u_k-x^* \right\Vert^2
\leq 4M^2\left(\prob{{min}}^{-1}+1\right)\leq \frac{8M^2}{\prob{{min}}}.
\end{align}
Summing over \cref{eqn:gap_prop_ineq2_a} from $k=1$ to $N$ and using \cref{eqn:gap_prop_ineq3_a}, we obtain:
\begin{align*}
&\sum_{k=1}^{N}\gamma_k^r\left(f(x_k)-f(x^*)\right) \leq \frac{\gamma_{0}^{r-1}}{2\eta_0} \left(  \mathcal{D}\left(x_1,x^*\right)  + \left\Vert u_1-x^* \right\Vert^2 \right) 
\nonumber \\ 
&+4M^2\prob{{min}}^{-1}\left(\frac{\gamma_{{N}}^{r-1}}{\eta_{N}} - \frac{\gamma_{{0}}^{r-1}}{\eta_{0}}\right)+\sum_{k=1}^{N}\eta_k^{-1}\left(\Theta_{k,1}+\Theta_{k,2}+\Theta_{k,3}\right),
\end{align*}
where we drop the nonpositive term. From relation \cref{eqn:gap_prop_ineq1_a} when $k=0$, we have:
\begin{align*}
\gamma_0^r\left(f(x_0)-f(x^*)\right)& \leq  \frac{\gamma_0^{r-1}}{2\eta_0}\left(\mathcal{D}\left(x_{0}, x^*\right) +\|u_0-x^*\|^2\right) \nonumber\\
&-\frac{\gamma_0^{r-1}}{2\eta_0}\left(\mathcal{D}\left(x_{1}, x^*\right) +\|u_{1}-x^*\|^2\right)+ \eta_0^{-1}\left(\Theta_{0,1}+\Theta_{0,2}+\Theta_{0,3}\right).
\end{align*}
Adding the last two inequalities, {multiplying and dividing the left-hand side by $\sum_{k=0}^{N}\gamma_k^r$, and then, invoking} \cref{Lemma 2.10} and convexity of $f$, we obtain:
\begin{align*}
&\left(\sum_{k=0}^{N}\gamma_k^r\right)\left(f\left(\bar x_N\right)-f(x^*)\right) \leq \frac{\gamma_{0}^{r-1}}{2\eta_0} \left(  \mathcal{D}\left(x_0,x^*\right)  + \left\Vert u_0-x^* \right\Vert^2 \right) 
\nonumber \\ 
&+4M^2\prob{{min}}^{-1}\left(\frac{\gamma_{{N}}^{r-1}}{\eta_{N}} - \frac{\gamma_{{0}}^{r-1}}{\eta_{0}}\right)+\sum_{k=0}^{N}\eta_k^{-1}\left( \Theta_{k,1}+\Theta_{k,2}+\Theta_{k,3}\right).
\end{align*}
Taking the expectation on both sides and invoking \cref{eqn:gap_prop_ineq3_a}, we obtain:
\begin{align*}
&\EXP{f\left(\bar x_N\right)}-f(x^*) \leq \frac{\frac{4M^2\prob{{min}}^{-1}\gamma_{{N}}^{r-1}}{\eta_{N}} +\sum_{k=0}^{N}\eta_k^{-1}\EXP{\Theta_{k,1}+\Theta_{k,2}+\Theta_{k,3}}}{\sum_{k=0}^{N}\gamma_k^r}.
\end{align*}
From the relations \cref{eqn:estimate_deltas_1_2} and \cref{eqn:estimate_deltas_3}, we obtain:
\begin{align*}
&\EXP{f\left(\bar x_N\right)}-f(x^*) \leq \frac{\frac{4M^2\prob{{min}}^{-1}\gamma_{{N}}^{r-1}}{\eta_{N}}+\sum_{k=0}^{N}\eta_k^{-1}\left(\prob{{min}}^{-1}\gamma_k^{r+1}\left(C_F^2+\eta_k^2C_f^2\right)\right)}{\sum_{k=0}^{N}\gamma_k^r},
\end{align*}
which implies the inequality \cref{eqn:f_bound}. 

\noindent (b) From the Cauchy-Schwarz inequality, the definitions of $C_f$ and $M$, and the triangle inequality, we have $ \tilde \nabla f(x_k)^T(y-x_k) \leq \left\| \tilde \nabla f(x_k)\right\|\|x_k-y\| \leq 2C_f M.$
Adding the preceding inequality with the relation \cref{eqn:prebound_gap}, {from \cref{eqn:three_terms_abr}} we obtain:
\begin{align}\label{eqn:prop_gap_proof_ineq0}
&\gamma_k^rF(y)^T(x_k-y) \leq \frac{\gamma_k^{r-1}}{2}\left(\mathcal{D}\left(x_{k}, y\right) +\|u_k-y\|^2\right) \nonumber\\
&-\frac{\gamma_k^{r-1}}{2}\left(\mathcal{D}\left(x_{k+1}, y\right) +\|u_{k+1}-y\|^2\right)+ 2\gamma_k^r\eta_kC_f M+ \Theta_{k,1}+\Theta_{k,2}+\Theta_{k,3}.
\end{align}
Adding and subtracting the term $\frac{\gamma_{{k-1}}^{r-1}}{2} \left( \mathcal{D}\left(x_k,y\right) + \left\Vert u_k-y \right\Vert^2 \right)$, we obtain:
\begin{align*}
			&\gamma_k^rF(y)^T(x_k-y) \leq  \frac{\gamma_{{k-1}}^{r-1}}{2} \left(  \mathcal{D}\left(x_k,y\right)  + \left\Vert u_k-y \right\Vert^2 \right) \nonumber \\
			&- \frac{\gamma_{{k}}^{r-1}}{2} \left(  \mathcal{D}\left(x_{k+1},y\right)  + \left\Vert u_{k+1}-y \right\Vert^2 \right)+ \frac{1}{2} \left(\gamma_{{k}}^{r-1} - \gamma_{{k-1}}^{r-1}\right)\left( \mathcal{D}\left(x_k,y\right) + \left\Vert u_k-y \right\Vert^2 \right)\nonumber \\
&+ 2\gamma_k^r\eta_kC_f M+ \Theta_{k,1}+\Theta_{k,2}+\Theta_{k,3}.
\end{align*}
Substituting the bound given by \cref{eqn:gap_prop_ineq3_a} in the preceding relation, we obtain:
\begin{align*}
			&\gamma_k^rF(y)^T(x_k-y) \leq  \frac{\gamma_{{k-1}}^{r-1}}{2} \left(  \mathcal{D}\left(x_k,y\right)  + \left\Vert u_k-y \right\Vert^2 \right) \nonumber \\
			&- \frac{\gamma_{{k}}^{r-1}}{2} \left(  \mathcal{D}\left(x_{k+1},y\right)  + \left\Vert u_{k+1}-y \right\Vert^2 \right)+ 4M^2\prob{{min}}^{-1} \left(\gamma_{{k}}^{r-1} - \gamma_{{k-1}}^{r-1}\right)\nonumber \\
&+ 2\gamma_k^r\eta_kC_f M+ \Theta_{k,1}+\Theta_{k,2}+\Theta_{k,3}.
\end{align*}
Summing both sides from $k = 1 $ to $N$, we obtain:
\begin{align}\label{eqn:prop_gap_proof_ineq1}
\sum_{k=1}^{N}\gamma_{{k}}^r F(y)^T \left(x_k-y\right)& \leq  \frac{\gamma_{{0}}^{r-1}}{2} \left( \mathcal{D}\left(x_1,y\right) + \left\Vert u_1-y \right\Vert^2 \right)+ 4 M^2\prob{{min}}^{-1} \left( \gamma_{{N}}^{r-1} - \gamma_{{0}}^{r-1}\right) \nonumber \\
			%&- \frac{\gamma_{{N}}^{r-1}}{2} \left(  \mathcal{D}\left(x_{N},y\right)  + \left\Vert u_{N}-y \right\Vert^2 \right) \nonumber \\
			& +\sum_{k=1}^{N}\left(  2\gamma_k^r\eta_kC_f M+ \Theta_{k,1}+\Theta_{k,2}+\Theta_{k,3}\right).
\end{align}
Writing the inequality \cref{eqn:prop_gap_proof_ineq0} for $k =0$, we have:
	\begin{align}\label{eqn:prop_gap_proof_ineq2}
\gamma_0^rF(y)^T(x_0-y) &\leq \frac{\gamma_0^{r-1}}{2}\left(\mathcal{D}\left(x_{0}, y\right) +\|u_0-y\|^2\right)-\frac{\gamma_0^{r-1}}{2}\left(\mathcal{D}\left(x_{1}, y\right) +\|u_{1}-y\|^2\right) \nonumber\\
&+ 2\gamma_0^r\eta_0C_f M+ \Theta_{0,1}+\Theta_{0,2}+\Theta_{0,3}.
\end{align}
Adding \cref{eqn:prop_gap_proof_ineq1} and \cref{eqn:prop_gap_proof_ineq2} together, we obtain:
\begin{align}\label{eqn:prop_gap_proof_ineq3}
\sum_{k=0}^{N}\gamma_{{k}}^r F(y)^T \left(x_k-y\right) &\leq  \frac{\gamma_{{0}}^{r-1}}{2} \left( \mathcal{D}\left(x_0,y\right) + \left\Vert u_0 -y \right\Vert^2 \right) + 4 M^2\prob{{min}}^{-1} \left( \gamma_{{N}}^{r-1} - \gamma_{{0}}^{r-1}\right) \nonumber \\& +\sum_{k=0}^{N}\left(  2\gamma_k^r\eta_kC_f M+ \Theta_{k,1}+\Theta_{k,2}+\Theta_{k,3}\right).
\end{align}
Recalling $\bar{x}_{N} = \sum_{k=0}^N \lambda_{k,N} x_k$ in \cref{Lemma 2.10}, applying the bound given by \cref{eqn:gap_prop_ineq3_a}, and using the triangle inequality, we obtain:
	\begin{align*}
\left(\sum_{k=0}^{N} \gamma_{{k}}^r \right) F(y)^T \left(\bar{x}_N-y\right) \leq& {4 M^2\prob{{min}}^{-1}  \gamma_{{N}}^{r-1} }  +\sum_{k=0}^{N}\left(  2\gamma_k^r\eta_kC_f M+ \Theta_{k,1}+\Theta_{k,2}+\Theta_{k,3}\right).
\end{align*}
Taking the supremum with respect to $y$ over the set $X$ from the left-hand side, invoking \cref{def:gap}, and then dividing both sides by $\sum_{k=0}^{N} \gamma_{{k}}^r $, we obtain:
	\begin{align*}
\text{GAP}\left(\bar x_N\right) \leq \frac{4 M^2\prob{{min}}^{-1}  \gamma_{{N}}^{r-1}   +\sum_{k=0}^{N}\left(  2\gamma_k^r\eta_kC_f M+ \Theta_{k,1}+\Theta_{k,2}+\Theta_{k,3}\right)}{\sum_{k=0}^{N} \gamma_{{k}}^r }.
\end{align*}
Taking the expectation on both sides, using the relations \cref{eqn:estimate_deltas_1_2} and \cref{eqn:estimate_deltas_3}, and rearranging the terms, we obtain the inequality \cref{eqn:gap_bound}.
\end{proof}

\begin{proof} Let us define the following terms: 
\begin{align*}%\label{eqn:three_terms_abr2}
& \Lambda_{N,1} \triangleq \prob{{min}}\sum_{k=0}^{N}\gamma_k^r, \quad  \Lambda_{N,2}\triangleq  \frac{4M^2\gamma_{{N}}^{r-1}}{\eta_{N}} ,\quad \Lambda_{N,3} \triangleq \left(C_F^2+\eta_0^2C_f^2\right)\sum_{k=0}^{N}\eta_k^{-1}\gamma_k^{r+1},\nonumber\\ 
& \Lambda_{N,4} \triangleq 4M^2\gamma_{{N}}^{r-1}, \quad  \Lambda_{N,5} \triangleq \left(C_F^2+\eta_0^2C_f^2\right)\sum_{k=0}^{N}\gamma_k^{r+1}, \quad \Lambda_{N,6} \triangleq 2\prob{{min}}C_fM \sum_{k=0}^{N}\eta_k\gamma_k^r.
\end{align*}
Note that from \cref{eqn:f_bound} and \cref{eqn:gap_bound}, we have:
\begin{align}\label{eqn:bounds_in_Lambdas}
\EXP{f\left(\bar x_N\right)}-f(x^*) \leq \frac{\Lambda_{N,2}+\Lambda_{N,3}}{\Lambda_{N,1}}, \quad \EXP{\text{GAP}\left(\bar{x}_N\right)} \leq \frac{\Lambda_{N,4}+\Lambda_{N,5}+\Lambda_{N,6}}{\Lambda_{N,1}}.
\end{align}
Next, we apply \cref{Lemma 2.13} to estimate the terms $\Lambda_{N,i}$. Substituting $\gamma_k$ and $\eta_k$ by their update rules, we obtain:
\begin{align*}%\label{eqn:Lambda1}
\Lambda_{N,1} &=\prob{{min}}\sum_{k=0}^{N}\frac{\gamma_0^r}{(k+1)^{0.5r}}\geq \frac{\prob{{min}}\gamma_0^r(N+1)^{1-0.5r}}{2(1-0.5r)},\\  
\Lambda_{N,2} &= \frac{4M^2(N+1)^{0.5(1-r)+b}}{\eta_0\gamma_0^{1-r}},\quad \Lambda_{N,4} = \frac{4M^2(N+1)^{0.5(1-r)}}{\gamma_0^{1-r}}, \\
\Lambda_{N,3} &= \sum_{k=0}^{N}\frac{\left(C_F^2+\eta_0^2C_f^2\right)\gamma_0^{1+r}}{\eta_0(k+1)^{0.5(1+r)-b}} \leq\frac{\gamma_0^{1+r}\left(C_F^2+\eta_0^2C_f^2\right)(N+1)^{1-0.5(1+r)+b}}{\eta_0(1-0.5(1+r)+b)},\\
\Lambda_{N,5} &= \left(C_F^2+\eta_0^2C_f^2\right)\sum_{k=0}^{N}\frac{\gamma_0^{r+1}}{(k+1)^{0.5(1+r)}}\leq \frac{\left(C_F^2+\eta_0^2C_f^2\right)\gamma_0^{r+1}(N+1)^{1-0.5(1+r)}}{1-0.5(1+r)},\\
\Lambda_{N,6} &=2\prob{{min}}C_fM \eta_0\gamma_0^r\sum_{k=0}^{N}\frac{1}{(k+1)^{0.5r+b}}\leq  \frac{2\prob{{min}}C_fM \eta_0\gamma_0^r (N+1)^{1-0.5r-b}}{1-0.5r-b}.
\end{align*}
For these inequalities to hold, we need to ensure that {the} conditions of \cref{Lemma 2.13} are met. Accordingly, we must have $0\leq 0.5r <1$, $0\leq 0.5(1+r)-b <1$, $0\leq 0.5r+b<1$, and $0 \leq 0.5(1+r)<1$. These relations hold because $0\leq r<1$ and $0<b<0.5$. Another set of conditions when applying \cref{Lemma 2.13} includes $N\geq \max\left\{2^{1/(1-0.5r)},2^{1/(1-0.5(1+r)+b)},2^{1/(1-0.5r-b)},2^{1/(1-0.5(1+r))}\right\}-1$. {This relation is indeed} satisfied as a consequence of $N\geq 2^{\frac{2}{1-r}}-1$, {$0<b<0.5$}, and $0\leq r<1$. We conclude that all the necessary conditions for applying \cref{Lemma 2.13} and obtaining the aforementioned bounds for the terms $\Lambda_{N,i}$ are satisfied. To show that the inequalities \cref{eqn:f_rate} and \cref{eqn:gap_rate} hold, it suffices to substitute the preceding {bounds on} the terms $\Lambda_{N,i}$ into the two inequalities given by \cref{eqn:bounds_in_Lambdas}. The details are as follows:
\begin{align*}
&\EXP{f\left(\bar x_N\right)}-f(x^*) \leq \frac{\Lambda_{N,2}+\Lambda_{N,3}}{\Lambda_{N,1}}=\frac{2-r}{\prob{{min}}\gamma_0^r(N+1)^{1-0.5r}}\left(\frac{4M^2(N+1)^{0.5-0.5r+b}}{\eta_0\gamma_0^{1-r}}\right.\\
&\left.+\left(\frac{\gamma_0^{1+r}}{\eta_0}\right)\frac{\left(C_F^2+\eta_0^2C_f^2\right)(N+1)^{0.5-0.5r+b}}{0.5-0.5r+b}\right). 
\end{align*}
The inequality \cref{eqn:f_rate} is obtained by rearranging the terms in the preceding relation.
\begin{align*}
&\EXP{\text{GAP}\left(\bar{x}_N\right)} \leq \frac{\Lambda_{N,4}+\Lambda_{N,5}+\Lambda_{N,6}}{\Lambda_{N,1}} \leq\frac{2-r}{\prob{{min}}\gamma_0^r(N+1)^{1-0.5r}}\left(\frac{4M^2(N+1)^{0.5-0.5r}}{\gamma_0^{1-r}} \right.\\
&\left.+\frac{\left(C_F^2+\eta_0^2C_f^2\right)\gamma_0^{r+1}(N+1)^{0.5-0.5r}}{0.5-0.5r}+ \frac{2\prob{{min}}C_fM \eta_0\gamma_0^r (N+1)^{1-0.5r-b}}{1-0.5r-b}\right).
\end{align*}
Then, \cref{eqn:gap_rate} can be obtained by rearranging the terms in the preceding inequality.
\end{proof}

\subsection{Proof of \cref{Lemma 2.10}}\label{app:ave_x_second_formula}
We use induction to show $\bar{x}_{N} = \sum_{k=0}^N \lambda_{k,N} x_k$ for any $N\geq 0$. For $N=0$, the relation holds due to the initialization $\bar{x}_0 :=x_0$ in \cref{alg:aRB-IRG} and that $\lambda_{0,0}=1$. Next, let the relation hold for some $N\geq 0$. From {the hypothesis, equation \cref{eqn:ave_step_of_alg}, and} that $S_{N}=\sum_{k=0}^N\gamma_k^r$ for all $N\geq 0$, we can write: 
\begin{align*}
	\bar{x}_{N+1} = \frac{S_N\bar{x}_N + \gamma_{N+1}^r x_{N+1}}{S_{N+1}} 
	%= \frac{\sum_{k = 0}^{N}\gamma_k^r x_k + \gamma_{N+1}^r x_{N+1}}{S_{N+1}}
	 = \frac{\sum_{k=0}^{N+1}\gamma_k^r x_k}{\sum_{k = 0}^{N+1}\gamma_k^r} = \sum_{k=0}^{N+1} \lambda_{k,N+1} x_k,
	\end{align*}
implying that the induction hypothesis holds for $N+1$. Thus, we conclude that the desired averaging formula holds for {all} $N\geq 0$. To complete the proof, note that since $\sum_{k=0}^N \lambda_{k,N}=1$, under the convexity of the set $X$, we have $\bar x_N \in X$.
