\subsection{Proof of \cref{Lemma 2.12}}\label{app:deltas} (a) From \cref{def:deltas}, we can write:
\begin{align*} 
\EXP{\Delta_k\mid \mathcal{F}_k} =F(x_k)-\sum_{i=1}^d\prob{{i}}\prob{{i}}^{-1}{\mathbf{U}}_{i}F_{i}(x_k)= F(x_k) -\sum_{i=1}^d{\mathbf{U}}_{i}F_{i}(x_k) =0.
\end{align*}
The relation $\EXP{\delta_k\mid \mathcal{F}_k}=0$ can be shown in a similar fashion.

\noindent (b) We can write:
\begin{align*}
 &\EXP{\|\Delta_k\|^2\mid \mathcal{F}_k} = \sum_{i=1}^d\prob{{i}}\left\|F(x_k)-\prob{{i}}^{-1}{\mathbf{U}}_{i}F_{i}(x_k)\right\|^2\\
 &=  \sum_{i=1}^d\prob{{i}} \left(\|F(x_k)\|^2 +\prob{{i}}^{-2} \left\|{\mathbf{U}}_{i}F_{i}(x_k)\right\|^2 - 2\prob{{i}}^{-1}F(x_k)^T{\mathbf{U}}_{i}F_{i}(x_k)\right)\\
 & = \|F(x_k)\|^2 +\sum_{i=1}^d\prob{{i}}^{-1} \left\|{\mathbf{U}}_{i}F_{i}(x_k)\right\|^2  -2\sum_{i=1}^d\|F_i(x_k)\|^2 
 % \leq \left(\prob{{min}}^{-1}-1\right)\|F(x_k)\|^2 
 \leq \left(\prob{{min}}^{-1}-1\right)C_F^2.
\end{align*}
The relation $\EXP{\|\delta_k\|^2\mid \mathcal{F}_k} \leq  \left(\prob{{min}}^{-1}-1\right)C_f^2$ can be shown using a similar approach. 



\subsection{Proof of \cref{Lemma 2.13}}\label{app:harmonic_bounds} Given $0\leq \alpha <1$, let us define the function $\phi:\mathbb{R}_{++} \to \mathbb{R}$ as $\phi(x) \triangleq x^{-\alpha}$ for all $x>0$. Since $\alpha >0$, the function $\phi$ is nonincreasing. We can write:
\begin{align*}
\sum_{k=0}^{N}\frac{1}{(k+1)^\alpha}
%=\sum_{k=1}^{N+1}k^{-\alpha}
= 1 + \sum_{k=2}^{N+1}\frac{1}{k^\alpha}\leq 1+\int_{1}^{N+1}\frac{dx}{x^\alpha} =1+\frac{(N+1)^{1-\alpha}-1}{1-\alpha}\leq \frac{(N+1)^{1-\alpha}}{1-\alpha},
\end{align*}
implying the desired upper bound. To show that the lower bound holds, we can write:
\begin{align*}
\sum_{k=0}^{N}\frac{1}{(k+1)^\alpha}=\sum_{k=1}^{N+1}\frac{1}{k^\alpha}\geq \int_{1}^{N+2}\frac{dx}{x^\alpha} \geq \int_{1}^{N+1}\frac{dx}{x^\alpha}
%=\frac{(N+1)^{1-\alpha}-1}{1-\alpha} 
\geq \frac{(N+1)^{1-\alpha}-0.5(N+1)^{1-\alpha}}{1-\alpha},
\end{align*}
where the last inequality is obtained using the assumption that $N \geq 2^{\frac{1}{1-\alpha}}-1$. Therefore, the desired lower bound holds as well. This completes the proof.

