\begin{lemma}[Weighted averaging]\label{Lemma 2.10}
Let $\{\bar x_k\}$ be generated by \cref{alg:aRB-IRG}. Let us define the weights $\lambda_{k,N} \triangleq \frac{\gamma_k^r}{\sum_{j=0}^N \gamma_j^r}$ for $k \in \{0,\ldots, N\}$ and $N\geq 0$. Then, for any $N\geq 0$, we have $\bar{x}_{N} = \sum_{k=0}^N \lambda_{k,N} x_k$. Also, when $X$ is a convex set, we have $\bar x_N \in X$.
\end{lemma}

\begin{proof}
\begin{comment}
We use induction to show that $\bar{x}_{N} = \sum_{k=0}^N \lambda_{k,N} x_k$ for any $N\geq 0$. For $N=0$, the relation holds due to the initialization $\bar{x}_0 :=x_0$ in \cref{alg:aRB-IRG} and that $\lambda_{0,0}=1$. Next, let the relation hold for some $N\geq 0$. From \cref{eqn:ave_step_of_alg} and noting that $S_{N}=\sum_{k=0}^N\gamma_k^r$ for any $N\geq 0$, we can write the following: 
\begin{align*}
	\bar{x}_{N+1} = \frac{S_N\bar{x}_N + \gamma_{N+1}^r x_{N+1}}{S_{N+1}} 
	%= \frac{\sum_{k = 0}^{N}\gamma_k^r x_k + \gamma_{N+1}^r x_{N+1}}{S_{N+1}}
	 = \frac{\sum_{k=0}^{N+1}\gamma_k^r x_k}{\sum_{k = 0}^{N+1}\gamma_k^r} = \sum_{k=0}^{N+1} \lambda_{k,N+1} x_k,
	\end{align*}
implying that the induction hypothesis holds for $N+1$. Thus, we conclude that the desired averaging formula holds for $N\geq 0$. To complete the proof, note that since $\sum_{k=0}^N \lambda_{k,N}=1$, under the convexity of the set $X$, we have $\bar x_N \in X$.
\end{comment}
See \cref{app:ave_x_second_formula}. 
\end{proof}

