 &=  \sum_{i=1}^d\prob{{i}} \left(\|F(x_k)\|^2 +\prob{{i}}^{-2} \left\|{\mathbf{U}}_{i}F_{i}(x_k)\right\|^2 - 2\prob{{i}}^{-1}F(x_k)^T{\mathbf{U}}_{i}F_{i}(x_k)\right)\\
