\begin{algorithm} [h]
	\caption{aRB-IRG}
	\begin{algorithmic}[1]
		\STATE\textbf{Input:} A random initial point $x_0 \in X$, $\bar{x}_0 := x_0$, initial stepsize $\gamma_{0} > 0$, initial regularization parameter $\eta_{0} > 0$, a scalar $0\leq r<1$, and $S_0 := \gamma_0^r$.
		\FOR{k = 0, 1, \dots}
		\STATE Generate a realization of random variable $i_k$ according to \cref{assum:random sample}.
		\STATE Evaluate $F_{i_k}(x_k)$ and $\tilde \nabla_{i_k} f(x_k)$ where $\tilde \nabla f(x_k) \in \partial f(x_k)$.

		\STATE Update $x_k$ as follows:
%				${x_{k+1}^{(i)}} :=$
		\begin{align}\label{equ:update_rule_aRBIRG} 
		{x_{k+1}^{(i)}} :=
		\begin{cases}
		\proj[X_{i_k}]{ x_{k}^{(i_k)}-\gamma_{k}\left(F_{i_k}\left( x_{k}\right) + \eta_{k} \tilde \nabla_{{i_k}} f\left( x_{k}\right)\right)}& \text{ if } i = i_k, \\
		x_k^{(i)} & \text{ if } i \neq i_k. 
		\end{cases}
		\end{align}
		\STATE Obtain $\gamma_{k+1}$ and $\eta_{k+1}$ (cf. \cref{thm:a-IRG_rate_results} and \cref{thm:convergence_RB-IRG} for the update rules).

		\STATE Update the averaged iterate $\bar{x}_{k}$ as follows:
			\begin{align}\label{eqn:ave_step_of_alg}
			S_{k+1} &:= S_k + \gamma_{k+1}^r,\quad	\bar{x}_{k+1}:= \frac{S_k\bar{x}_{k}+\gamma_{k+1}^rx_{k+1}}{S_{k+1}}.
			\end{align}
		\ENDFOR
	\end{algorithmic} \label{alg:aRB-IRG}
\end{algorithm}

\begin{assumption}[Block-coordinate selection rule] \label{assum:random sample}
At each iteration $k\geq 0$, the random variable $i_k$ is generated from an independent and identically distributed discrete probability distribution such that $\mathrm{Prob}\left(i_k=i\right) = \prob{i}$ where $ \prob{i}>0$ for $i \in \{1,\ldots,d\}$ and $\sum_{i=1}^{d}\prob{i}=1$.
\end{assumption}

\begin{definition}[Distance function]\label{def:err_D}
	For any $x,y \in \mathbb{R}^n$, function $\mathcal{D}(x,y)$ is defined as $
	\mathcal{D}(x,y)\triangleq \sum_{i=1}^{d} \prob{i}^{-1} \left\Vert\left. x^{(i)}-y^{(i)} \right\Vert\right.^2$, where $\prob{i}$ is given by \cref{assum:random sample}.
	% 	, where $\prob{i}$ is the uniform probability of selection of any block  $i$. From \cref{assum:random sample}, we have $\prob{i} = \frac{1}{d}.$ So, we write  $ \mathcal{D}(x,y) =  d \sum_{i=1}^{d}  \left\Vert\left. x^{(i)}-y^{(i)} \right\Vert\right.^2$.
\end{definition}

\begin{remark} \label{rem:err_D}
Under \cref{assum:random sample}, we can relate the distance function $\mathcal{D}$ with the $\ell_2$--norm as follows: $\prob{{min}}	{\mathcal{D}(x,y)} \leq \|x-y\|^2 \leq\prob{{max}} {\mathcal{D}(x,y)}$ for all $x,y \in \mathbb{R}^n$, where  $\prob{{min}}\triangleq \min_{1\leq i \leq d}\{\prob{i}\}$ and $\prob{{max}}\triangleq \max_{1\leq i \leq d}\{\prob{i}\}$.
\end{remark}

\begin{definition}[The dual gap function \cite{MarcotteZhu1998}]\label{def:gap}
Let a nonempty closed set $X\subseteq \mathbb{R}^n$ and a mapping $F:X\rightarrow\mathbb{R}^n$ be given. Then, for any $x \in X$, the dual gap function $\mathrm{GAP}:X\rightarrow \mathbb{R}\cup \{+\infty\} $ is defined as $ \mathrm{GAP}(x) \triangleq \sup_{y\in X} F(y)^T(x-y)$.
\end{definition}

\begin{definition}[Regularized mapping]\label{def:reg_map}
Given a vector $x \in X$, a subgradient $\tilde \nabla f(x) \in \partial f(x)$, and an integer $k\geq 0$, the regularized mapping $G_k: X \to \mathbb{R}$ is defined as $G_k(x) \triangleq F(x)+\eta_k\tilde \nabla f(x)$. The $i^\text{th}$ {block-coordinate} of $G_k$ is denoted by $G_{k,i}$.
\end{definition}

\begin{definition}[History of the method]\label{def:Fk}
Throughout, we let the history of the algorithm to be denoted by $\mathcal{F}_k \triangleq \{x_0,i_0,i_1,\ldots,i_{k-1}\}$ for $k\geq 1$, with $\mathcal{F}_0 \triangleq \{x_0\}$.
\end{definition}

\begin{definition}[Randomized block error terms]\label{def:deltas}
Let ${\mathbf{U}}_i \in \mathbb{R}^{n\times n_i}$ for $i=1,\ldots,d$ be the collection of matrices such that $\mathbf{I}_n = \left[{\mathbf{U}}_1,\ldots,{\mathbf{U}}_d\right] \in \mathbb{R}^{n\times n}$. Consider the following definitions for $k\geq 0$: 
\begin{align}\label{eqn:deltas}
\Delta_k\triangleq F(x_k) - \prob{{i_k}}^{-1}{\mathbf{U}}_{i_k}F_{i_k}(x_k), \qquad \delta_k\triangleq \tilde \nabla f(x_k) - \prob{{i_k}}^{-1}{\mathbf{U}}_{i_k} \tilde \nabla_{i_k}f (x_k).
\end{align}
\end{definition}

\begin{theorem}[Convergence rate statements for \cref{alg:aRB-IRG}]\label{thm:a-IRG_rate_results}
Consider \cref{alg:aRB-IRG}. Let \cref{assum:problem} and \cref{assum:random sample} hold and assume {that} the set $X$ is bounded such that $\|x\|\leq M$ for all $x \in X$ and some $M>0$. Suppose for {all} $k\geq 0$, $\gamma_k:=\frac{\gamma_0}{\sqrt{k+1}}$ and $\eta_k:=\frac{\eta_0}{(k+1)^b}$, where $\gamma_0>0$, $\eta_0>0$, and $0<b<0.5$. Then, for any $0\leq r <1$, the following results hold:\\
\noindent (i) Let $x^*$ be an optimal solution to the problem \cref{prob:main}. Then, for {all} $N\geq 2^{\frac{2}{1-r}}-1$:
\begin{align}\label{eqn:f_rate} 
&\EXP{f\left(\bar x_N\right)}-f(x^*) \leq \frac{2-r}{\prob{{min}}\eta_0}\left(\frac{4M^2}{\gamma_0}+\frac{\gamma_0\left(C_F^2+\eta_0^2C_f^2\right)}{0.5-0.5r+b}\right)\frac{1}{(N+1)^{0.5-b}}.
\end{align}
\noindent (ii) Consider the dual gap function in \cref{def:gap}. Then, for {all} $N\geq 2^{\frac{2}{1-r}}-1$:
\begin{align}\label{eqn:gap_rate} 
\EXP{\mathrm{GAP}\left(\bar{x}_N\right)} \leq \frac{2-r}{\prob{{min}}}\left(\frac{4M^2}{\gamma_0}+\frac{\gamma_0\left(C_F^2+\eta_0^2C_f^2\right)}{0.5-0.5r}+\frac{2\prob{{min}C_fM}\eta_0}{1-0.5r-b}\right)\frac{1}{(N+1)^b}.
\end{align}
\end{theorem}

