			&\gamma_k^rF(y)^T(x_k-y) \leq  \frac{\gamma_{{k-1}}^{r-1}}{2} \left(  \mathcal{D}\left(x_k,y\right)  + \left\Vert u_k-y \right\Vert^2 \right) \nonumber \\
			&- \frac{\gamma_{{k}}^{r-1}}{2} \left(  \mathcal{D}\left(x_{k+1},y\right)  + \left\Vert u_{k+1}-y \right\Vert^2 \right)+ 4M^2\prob{{min}}^{-1} \left(\gamma_{{k}}^{r-1} - \gamma_{{k-1}}^{r-1}\right)\nonumber \\
&+ 2\gamma_k^r\eta_kC_f M+ \Theta_{k,1}+\Theta_{k,2}+\Theta_{k,3}.
\end{align*}

Summing both sides from $k = 1 $ to $N$, we obtain:
\begin{align}\label{eqn:prop_gap_proof_ineq1}
\sum_{k=1}^{N}\gamma_{{k}}^r F(y)^T \left(x_k-y\right)& \leq  \frac{\gamma_{{0}}^{r-1}}{2} \left( \mathcal{D}\left(x_1,y\right) + \left\Vert u_1-y \right\Vert^2 \right)+ 4 M^2\prob{{min}}^{-1} \left( \gamma_{{N}}^{r-1} - \gamma_{{0}}^{r-1}\right) \nonumber \\
			%&- \frac{\gamma_{{N}}^{r-1}}{2} \left(  \mathcal{D}\left(x_{N},y\right)  + \left\Vert u_{N}-y \right\Vert^2 \right) \nonumber \\
			& +\sum_{k=1}^{N}\left(  2\gamma_k^r\eta_kC_f M+ \Theta_{k,1}+\Theta_{k,2}+\Theta_{k,3}\right).
\end{align}

Writing the inequality \cref{eqn:prop_gap_proof_ineq0} for $k =0$, we have:
	\begin{align}\label{eqn:prop_gap_proof_ineq2}
\gamma_0^rF(y)^T(x_0-y) &\leq \frac{\gamma_0^{r-1}}{2}\left(\mathcal{D}\left(x_{0}, y\right) +\|u_0-y\|^2\right)-\frac{\gamma_0^{r-1}}{2}\left(\mathcal{D}\left(x_{1}, y\right) +\|u_{1}-y\|^2\right) \nonumber\\
&+ 2\gamma_0^r\eta_0C_f M+ \Theta_{0,1}+\Theta_{0,2}+\Theta_{0,3}.
\end{align}

Adding \cref{eqn:prop_gap_proof_ineq1} and \cref{eqn:prop_gap_proof_ineq2} together, we obtain:
\begin{align}\label{eqn:prop_gap_proof_ineq3}
\sum_{k=0}^{N}\gamma_{{k}}^r F(y)^T \left(x_k-y\right) &\leq  \frac{\gamma_{{0}}^{r-1}}{2} \left( \mathcal{D}\left(x_0,y\right) + \left\Vert u_0 -y \right\Vert^2 \right) + 4 M^2\prob{{min}}^{-1} \left( \gamma_{{N}}^{r-1} - \gamma_{{0}}^{r-1}\right) \nonumber \\& +\sum_{k=0}^{N}\left(  2\gamma_k^r\eta_kC_f M+ \Theta_{k,1}+\Theta_{k,2}+\Theta_{k,3}\right).
\end{align}

Recalling $\bar{x}_{N} = \sum_{k=0}^N \lambda_{k,N} x_k$ in \cref{Lemma 2.10}, applying the bound given by \cref{eqn:gap_prop_ineq3_a}, and using the triangle inequality, we obtain:
	\begin{align*}
\left(\sum_{k=0}^{N} \gamma_{{k}}^r \right) F(y)^T \left(\bar{x}_N-y\right) \leq& {4 M^2\prob{{min}}^{-1}  \gamma_{{N}}^{r-1} }  +\sum_{k=0}^{N}\left(  2\gamma_k^r\eta_kC_f M+ \Theta_{k,1}+\Theta_{k,2}+\Theta_{k,3}\right).
\end{align*}

Taking the supremum with respect to $y$ over the set $X$ from the left-hand side, invoking \cref{def:gap}, and then dividing both sides by $\sum_{k=0}^{N} \gamma_{{k}}^r $, we obtain:
	\begin{align*}
\text{GAP}\left(\bar x_N\right) \leq \frac{4 M^2\prob{{min}}^{-1}  \gamma_{{N}}^{r-1}   +\sum_{k=0}^{N}\left(  2\gamma_k^r\eta_kC_f M+ \Theta_{k,1}+\Theta_{k,2}+\Theta_{k,3}\right)}{\sum_{k=0}^{N} \gamma_{{k}}^r }.
\end{align*}
Taking the expectation on both sides, using the relations \cref{eqn:estimate_deltas_1_2} and \cref{eqn:estimate_deltas_3}, and rearranging the terms, we obtain the inequality \cref{eqn:gap_bound}.
\end{proof}

